import base64, json, pathlib, shutil, subprocess, sys, urllib.request, zipfile

ROOT = pathlib.Path('/kaggle/working/memory_feedback_v3_closure_pkg')
PACKAGE = pathlib.Path('/kaggle/working/memory_feedback_v3_closure_pkg.zip')
PACKAGE.write_bytes(base64.b64decode(''))
if ROOT.exists(): shutil.rmtree(ROOT)
ROOT.mkdir(parents=True)
with zipfile.ZipFile(PACKAGE) as archive: archive.extractall(ROOT)
print('V3_CLOSURE_PACKAGE_READY', ROOT, sorted(p.name for p in ROOT.iterdir()), flush=True)

def json_read(path):
    try: return json.loads(path.read_text(encoding='utf-8'))
    except Exception: return {}

def nested(config, name, default=None):
    if name in config: return config[name]
    args = config.get('args', {})
    return args.get(name, default) if isinstance(args, dict) else default

def endpoint_metadata(directory):
    checkpoint = directory / 'checkpoint.pkl'
    config = json_read(directory / 'config.json')
    progress = json_read(directory / 'progress.json')
    if not checkpoint.is_file() or not config or not progress: return None
    rows = progress.get('rows', [])
    last = rows[-1] if rows else progress
    step = int(last.get('step', progress.get('step', progress.get('optimizer_steps', -1))))
    chars = int(last.get('processed_characters', progress.get('processed_characters', step * 4096)))
    params = int(config.get('params', config.get('parameter_count', -1)))
    seed = int(nested(config, 'seed', progress.get('seed', -1)))
    model = str(nested(config, 'model', config.get('model_name', '')))
    text = (str(directory) + ' ' + model + ' ' + json.dumps(config)).lower()
    if step != 25000 or chars != 102400000 or params != 47437768: return None
    if seed != 1 and 'seed_1' not in text and 'seed1' not in text: return None
    return {'directory': directory, 'checkpoint': checkpoint, 'model': model, 'text': text, 'seed': seed}

endpoints = []
for base in (pathlib.Path('/kaggle/input'), pathlib.Path('/kaggle/working')):
    if not base.exists(): continue
    for progress in base.rglob('progress.json'):
        metadata = endpoint_metadata(progress.parent)
        if metadata: endpoints.append(metadata)

def select(role):
    if role == 'candidate':
        matches = [row for row in endpoints if 'segment' in row['text'] and 'retention' in row['text']]
    else:
        matches = [row for row in endpoints if 'memoryfeedbackarchive' in row['text'].replace('_','').replace('-','') and not ('segment' in row['text'] and 'retention' in row['text'])]
    if not matches:
        details = [(str(row['directory']), row['model'], row['seed']) for row in endpoints]
        raise RuntimeError(f'No seed-1 {role} step-25,000 endpoint found. Eligible endpoints: {details}')
    matches.sort(key=lambda row: (
        0 if str(row['directory']).startswith('/kaggle/input') else 1,
        len(str(row['directory'])),
        str(row['directory'])
    ))
    selected = matches[0]
    print('V3_CLOSURE_ENDPOINT_SELECTED', role, selected['checkpoint'], selected['model'], flush=True)
    if len(matches) > 1:
        print('V3_CLOSURE_DUPLICATE_ENDPOINTS_IGNORED', role, [str(row['checkpoint']) for row in matches[1:]], flush=True)
    return selected['checkpoint']

CANDIDATE = select('candidate')
CANONICAL = select('canonical')
if CANDIDATE.resolve() == CANONICAL.resolve(): raise RuntimeError('Candidate and canonical checkpoints resolved to the same file')

DATA = pathlib.Path('/kaggle/working/enwik8')
if not DATA.is_file() or DATA.stat().st_size != 100_000_000:
    attached = [p for p in pathlib.Path('/kaggle/input').rglob('enwik8') if p.is_file() and p.stat().st_size == 100_000_000]
    if attached: shutil.copy2(attached[0], DATA)
    else:
        urllib.request.urlretrieve('https://data.deepai.org/enwik8.zip', '/kaggle/working/enwik8.zip')
        with zipfile.ZipFile('/kaggle/working/enwik8.zip') as archive:
            member = next(name for name in archive.namelist() if name.endswith('enwik8'))
            with archive.open(member) as source, DATA.open('wb') as target: shutil.copyfileobj(source, target)
if DATA.stat().st_size != 100_000_000: raise RuntimeError('Canonical enwik8 size check failed')
print('V3_CLOSURE_DATA_READY', DATA, DATA.stat().st_size, flush=True)

OUT = pathlib.Path('/kaggle/working/memory_feedback_v3_closure_results')
if OUT.exists(): shutil.rmtree(OUT)
OVER = OUT / 'seed_1_over_retention'
COORD = OUT / 'seed_1_paired_coordination'

over_command = [
    sys.executable, '-u', str(ROOT/'run_over_retention_audit.py'),
    '--data-path', str(DATA), '--checkpoint', str(CANDIDATE),
    '--code-root', str(ROOT), '--outdir', str(OVER), '--seed', '1'
]
print('RUN_SEED1_OVER_RETENTION_REPLICATION', ' '.join(over_command), flush=True)
over_completed = subprocess.run(over_command)
if over_completed.returncode:
    if OUT.exists(): shutil.make_archive('/kaggle/working/memory_feedback_v3_closure_partial', 'zip', OUT)
    raise RuntimeError(f'Seed-1 over-retention replication failed with code {over_completed.returncode}')

coord_command = [
    sys.executable, '-u', str(ROOT/'run_paired_endpoint_coordination_audit.py'),
    '--data-path', str(DATA), '--canonical-checkpoint', str(CANONICAL),
    '--candidate-checkpoint', str(CANDIDATE), '--code-root', str(ROOT),
    '--outdir', str(COORD), '--seed', '1'
]
print('RUN_PAIRED_ENDPOINT_COORDINATION_AUDIT', ' '.join(coord_command), flush=True)
coord_completed = subprocess.run(coord_command)
archive = shutil.make_archive('/kaggle/working/memory_feedback_v3_closure_results', 'zip', OUT)
print('V3_CLOSURE_ARCHIVE_READY', archive, flush=True)
if coord_completed.returncode: raise RuntimeError(f'Paired endpoint coordination audit failed with code {coord_completed.returncode}; outputs archived')

over_result = json_read(OVER/'over_retention_audit.json')
over = over_result.get('decision', {})
coord = json_read(COORD/'paired_endpoint_coordination_audit.json')
summary = {
    'seed': 1,
    'over_retention_screen_pass': over.get('over_retention_screen_pass'),
    'coordination_closure_pass': coord.get('coordination_closure_pass'),
    'candidate_minus_canonical_baseline_bpc': coord.get('candidate_minus_canonical_baseline_bpc'),
    'all_closure_gates_pass': bool(over.get('over_retention_screen_pass')) and bool(coord.get('coordination_closure_pass')),
    'test_data_read': False,
}
(OUT/'V3_CLOSURE_SUMMARY.json').write_text(json.dumps(summary, indent=2) + '\n', encoding='utf-8')
print('V3_CLOSURE_FINAL_DECISION', json.dumps(summary), flush=True)
print('V3_CLOSURE_CELL_COMPLETE', flush=True)
